export const COVERAGE_SOURCE_REVISION='6ba0dd43c0512ce8d5b0dae7150ae605f176c2fb';
export const COVERAGE_SNAPSHOT_REVISION='873b755c1760cbb068edbc15e5ebd083552078d326817503051956ec186eab66';
const coverageImportedRevision='236d059ce1e3c0442b4006abacf2ccd3f4de52bf2be92a3c644f62b8f49f30bf';
const coveragePackageSha256='ff6030be25daad5256737d8404a0b4c0612420bc94dbce30c052f4e3ceee6916';
export const coverageRegions={
 'head-neck':'Head and neck',spine:'Spine',thorax:'Thorax',abdomen:'Abdomen',pelvis:'Pelvis',
 'shoulder-arm':'Shoulder and arm',forearm:'Forearm',hand:'Hand',thigh:'Thigh',leg:'Leg',foot:'Foot',
} as const;
export type CoverageRegion=keyof typeof coverageRegions;
export type CoverageState='missing'|'held'|'partial'|'not-yet-inventoried';
export type CoverageView={
 sourceRevision:string;inventoryRevision:string;
 counts:{root:number;nested:number;specimenViews:number;specimenMemberships:number;specimenSelections:number;shoulder:number};
 targets:{id:string;label:string;state:CoverageState;regions:CoverageRegion[];reason:string}[];
 reference:{files:number;differences:number;nested:number;corrected:number;held:number;unsupported:number};
};
const labels={
 'upper-limb-peripheral-nerves':'Upper-limb peripheral nerves','lower-limb-peripheral-nerves':'Lower-limb peripheral nerves',
 'brachial-plexus':'Brachial plexus','lumbosacral-plexus':'Lumbosacral plexus','spinal-cord-tissue':'Spinal cord tissue',
 'nervous-system-completeness':'Nervous-system coverage','lymphatic-curriculum':'Lymphatic curriculum',
} as const;
export function coverageRegionQuery(params:Record<string,string|string[]|undefined>):CoverageRegion|null{
 if(Object.keys(params).some(k=>k!=='region')||Array.isArray(params.region))throw Error('Invalid region filter');
 if(params.region===undefined||params.region==='')return null;
 if(!Object.hasOwn(coverageRegions,params.region))throw Error('Invalid region filter');
 return params.region as CoverageRegion;
}
/** Metadata projection only: never a clinical decision, completeness score or new asset admission. */
async function digest(value:unknown){
 const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(value)));
 return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
}
export async function projectCoverageView(snapshot:unknown,manifest:unknown):Promise<CoverageView|null>{
 try{
  const s=structuredClone(snapshot) as any,m=structuredClone(manifest) as any;
  const hash=await digest(s);
  if(hash!==COVERAGE_SNAPSHOT_REVISION||s.sourceRevision!==COVERAGE_SOURCE_REVISION||m.revision!==COVERAGE_SOURCE_REVISION||!Array.isArray(m.files))return null;
  const byPath=new Map<string,any>();for(const f of m.files){if(typeof f.path!=='string'||byPath.has(f.path))return null;byPath.set(f.path,f);}
  let imported=0,metadataOnly=0;
  for(const[path,sha]of Object.entries(s.evidence.sourceInputs)){
   const f=byPath.get(path);if(f){if(f.sourceSha256!==sha)return null;imported++;}
   else{if(!(path==='package.json'&&sha===coveragePackageSha256)&&!/^(?:LICENSES\/bodyparts3d-v4-index\/|docs\/|scripts\/|content\/(?:reference-male-inventory|source-inventory)\.json$)/.test(path))return null;metadataOnly++;}
  }
  if(imported!==142||metadataOnly!==26||s.assessment.expectedCurriculumInventoried!==false||s.assessment.clinicalApprovalAsserted!==false||s.assessment.anatomicalCompletenessProven!==false)return null;
  const importedIdentity=Object.keys(s.evidence.sourceInputs).sort().flatMap(path=>{const f=byPath.get(path);return f?[{path,sourceSha256:f.sourceSha256,importedSha256:f.importedSha256}]:[];});
  if(await digest(importedIdentity)!==coverageImportedRevision)return null;
  const c=s.scopedCounts,r=c.reference.currentDifferenceCategories;
  const targets=s.documentedRootTargetGroups.map((t:any)=>{
   if(!Object.hasOwn(labels,t.id)||!['missing','held','partial','not-yet-inventoried'].includes(t.state)||!Array.isArray(t.regions)||t.regions.some((v:unknown)=>typeof v!=='string'||!Object.hasOwn(coverageRegions,v))||typeof t.reason!=='string')throw Error('Invalid target');
   return {id:t.id,label:labels[t.id as keyof typeof labels],state:t.state,regions:[...t.regions],reason:t.reason};
  });
  return {sourceRevision:s.sourceRevision,inventoryRevision:hash,
   counts:{root:c.root.rootRepresentations,nested:c.nested.nestedSelections,specimenViews:c.independent.independentViews,specimenMemberships:c.independent.independentSelectionMemberships,specimenSelections:c.independent.independentFrameQualifiedSelectionIds,shoulder:c.independent.dedicatedShoulderSelections},targets,
   reference:{files:c.reference.referenceFiles,differences:c.reference.currentRootDifferences,nested:r['admitted-current-or-reachable-nested'],corrected:r['reviewed-source-difference-or-overlap'],held:r['source-condition-or-identity-hold'],unsupported:r['unsupported-no-current-evidence']}};
 }catch{return null;}
}
/** Call after reviewer authorization; only a sanitized summary leaves this loader. */
export async function verifiedCoverageView():Promise<CoverageView|null>{
 const [{default:snapshot},{default:manifest}]=await Promise.all([import('../docs/anatomy-coverage/index.json'),import('../atlas-review/manifest.json')]);
 return projectCoverageView(snapshot,manifest);
}

// Reproducible, read-only import from the separately versioned Atlas handoff.
// Run with the Atlas repository path; never read its changing working tree.
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, posix } from 'node:path';
import { createHash } from 'node:crypto';
import ts from 'typescript';

const repository = process.argv[2];
if (!repository) throw Error('Supply the Atlas repository path');
const revision = '6ba0dd43c0512ce8d5b0dae7150ae605f176c2fb';
const git = (...args) => execFileSync('git', ['-C', repository, ...args], { maxBuffer: 64 * 1024 * 1024 });
const names = new Set(git('ls-tree', '-r', '--name-only', revision).toString().trim().split('\n'));
const output = 'atlas-review';
const files = new Map(), packages = new Set();
const seeds = ['app/review/overview/page.tsx', 'app/review/page.tsx', 'app/review/body/page.tsx', 'app/review/nested/page.tsx', 'app/review/specimens/page.tsx',
  'app/body-explorer.tsx', 'app/shoulder-explorer.tsx', 'app/globals.css', 'app/abdominal-wall-study.tsx', 'app/back-layers-study.tsx', 'app/hra-renal-study.tsx', 'app/hra-pelvis-study.tsx', 'app/um-limb-study.tsx', 'db/schema.ts', 'LICENSES/THIRD_PARTY_NOTICES.md',
  ...['reviews', 'body-review', 'body-review/decisions', 'nested-review', 'specimen-review', 'review-overview'].map(p => `app/api/${p}/route.ts`)];
function resolveImport(file, specifier) {
  const base = specifier.startsWith('@/') ? specifier.slice(2) : posix.normalize(posix.join(posix.dirname(file), specifier));
  const found = [base, ...['.ts', '.tsx', '.json', '.css', '/index.ts', '/index.tsx'].map(ext => base + ext)].find(p => names.has(p));
  if (!found) throw Error(`Missing import ${file}: ${specifier}`);
  return found;
}
function visit(file) {
  if (files.has(file)) return;
  const original = git('show', `${revision}:${file}`).toString();
  files.set(file, original);
  if (!/\.[cm]?[jt]sx?$/.test(file)) return;
  for (const { fileName: specifier } of ts.preProcessFile(original, true, true).importedFiles) {
    if (specifier.startsWith('.') || specifier.startsWith('@/')) visit(resolveImport(file, specifier));
    else packages.add(specifier.startsWith('@') ? specifier.split('/').slice(0, 2).join('/') : specifier.split('/')[0]);
  }
}
seeds.forEach(visit);
const routes = [
  ['/review/overview', '/workspace/atlas-review'],
  ['/review/body', '/workspace/atlas-review/body'],
  ['/review/nested', '/workspace/atlas-review/nested'],
  ['/review/specimens', '/workspace/atlas-review/specimens'],
  ['/review', '/workspace/atlas-review/shoulder'],
];
const sha = value => createHash('sha256').update(value).digest('hex');
const manifest = [];
for (const [file, original] of files) {
  let text = original;
  if (/\.[cm]?[jt]sx?$/.test(file)) {
    text = text.replace(/(['"])@\//g, '$1@/atlas-review/');
    // Keep transport separate from source/material/checklist content.
    for (const [from, to] of routes) text = text.replace(new RegExp(`(['"\x60])${from}(?=[?'"\x60])`, 'g'), `$1${to}`);
    for (const endpoint of ['review-overview', 'body-review', 'nested-review', 'specimen-review', 'reviews'])
      text = text.replaceAll('/api/' + endpoint, '/api/atlas-review/' + endpoint);
    for (const table of ['nested_review_events', 'specimen_review_events', 'body_review_events', 'review_events'])
      text = text.replace(new RegExp(`\\b${table}\\b`, 'g'), 'atlas_personal_' + table);
    // Website-owned links are adapted at the navigation boundary; fingerprints
    // and the source-bound query fields remain owned by the Atlas source.
    if (file.startsWith('app/review/')) {
      // This unadmitted source candidate has no website route or registered
      // model. Keep its independent Atlas inspector out of the approval UI.
      if (file === 'app/review/overview/page.tsx') text = text.replace(
        '        <p><Link href="/review/candidates/skin">Inspect the skin candidate (read-only)</Link> — separate from approval-ready selections.</p>\n',
        '',
      );
      if (text.includes('fetch(')) {
        text = text.replaceAll('fetch(', 'clinicalReviewFetch(')
          .replace(/(import )/, "import { clinicalReviewFetch } from '@/lib/clinical-review-fetch';\n$1");
      }
      text = text.replace(/(<(?:Link|a) href=)(\{(?:material|packet)\.atlasLink\})/g, '$1{reviewModelHref($2)}');
      if (file === 'app/review/review-model-preview.tsx') {
        const marker = '  const local =';
        if (text.split(marker).length !== 2) throw Error('Unexpected model preview adapter boundary');
        text = text.replace(marker, '  href = reviewModelPreviewHref(href);\n' + marker)
          .replace(/(import )/, "import { reviewModelPreviewHref } from '@/lib/clinical-review-links';\n$1");
      }
      text = text.replaceAll('reviewModelHref({material.atlasLink})', 'reviewModelHref(material.atlasLink)')
        .replaceAll('reviewModelHref({packet.atlasLink})', 'reviewModelHref(packet.atlasLink)');
      if (text.includes('reviewModelHref(')) text = text.replace(/(import )/, "import { reviewModelHref } from '@/lib/clinical-review-links';\n$1");
      text = text.replaceAll('<Link href="/imaging/local">Local CT study</Link>', '')
        .replaceAll('href="/shoulder"', 'href="/workspace/atlas-review/model?kind=shoulder"')
        .replaceAll('`/shoulder?structure=', '`/workspace/atlas-review/model?kind=shoulder&structure=')
        .replaceAll('href="/"', 'href="/atlas"')
        .replaceAll('href="/models/bodyparts3d/credits.html"', 'href="/atlas-runtime/shoulder/models/bodyparts3d/credits.html"');
    }
    if (file.startsWith('app/api/')) {
      text = text.replaceAll('authenticatedReviewer(request.headers)', 'await authenticatedReviewer(request.headers)');
      text = text.replaceAll('return env.DB;', "return env.DB.withSession('first-primary') as unknown as D1Database;")
        .replaceAll('(request, env.DB)', "(request, env.DB.withSession('first-primary') as unknown as D1Database)");
    }
  }
  if (file === 'app/globals.css') text = text.replace("@import 'shadcn/tailwind.css';", "@import '../../components/review-ui-variants.css';");
  const path = output + '/' + file;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
  manifest.push({ path: file, sourceSha256: sha(original), importedSha256: sha(text) });
}
writeFileSync(output + '/manifest.json', JSON.stringify({ revision, files: manifest, packages: [...packages].sort() }, null, 2) + '\n');
console.log(JSON.stringify({ revision, files: files.size, bytes: [...files.values()].reduce((n,t)=>n+Buffer.byteLength(t),0), packages: [...packages].sort() }));
